#include "aa2cc32d10adbc8c_constructor_tail.hpp"
namespace recovered_constructor_tail{void update_timer(U s,U value,U scratch,Ports&p){U server=p.server();U player=p.player(server,p.player_id(server));if(player){U head=p.read(p.read(p.read(player+12)));p.write(scratch,head);while(head){U item=p.at(p.read(p.read(player+12)),head);if(p.read(item+0x2c)==p.read(s+4)){p.write(item+0x150,value);return;}p.next(p.read(p.read(player+12)),scratch);head=p.read(scratch);}}p.write(s+0x20c,value);}
void recompute(U s,Ports&p){bool enabled=p.byte(s+0x4d1)==1;U i=p.half(p.read(s+0xa74)+0x160);while(static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(s+0x128))){U e=p.read(p.read(s+0x124)+4*i);U type=p.cell(0x746768);if(static_cast<std::int32_t>(p.half(e+8))>static_cast<std::int32_t>(type))break;if(p.half(e+8)==type&&(p.byte(e+10)&7)==p.cell(0x7473c8)&&p.effect_value(e,0)==1){U low=p.read(e),high=p.read(e+4);p.remove(s,low,high);i=p.half(p.read(s+0xa74)+0x160);}else ++i;}
 i=p.half(p.read(s+0xa74)+0x162);if(static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(s+0x128))){U type=p.cell(0x7466f0);do{U e=p.read(p.read(s+0x124)+4*i);if(static_cast<std::int32_t>(p.half(e+8))>static_cast<std::int32_t>(type))break;if(p.half(e+8)==type&&(p.byte(e+10)&7)==p.cell(0x7473c8)&&p.read(e+0x18)==p.read(s+4)){U low=p.read(e),high=p.read(e+4);p.remove(s,low,high);i=p.half(p.read(s+0xa74)+0x162);type=p.cell(0x7466f0);}else ++i;}while(static_cast<std::int32_t>(i)<static_cast<std::int32_t>(p.read(s+0x128)));}
 if(enabled){U e=p.allocate(0x8c);if(e)e=p.construct_effect(e,1);U type=p.cell(0x746768)&65535;U bits=p.half(e+10);p.put_half(e+8,type);bits=(bits&0xfff8)|p.cell(0x7473c8);p.write(e+0x20,0);p.put_half(e+10,bits);p.creator(e,p.read(s+4));p.effect_integer(e,0,1);p.apply(s,e,0,0);}}
void enable(U s,U flag,Ports&p){flag&=255;if(flag==p.byte(s+0x4d0))return;p.put_byte(s+0x4d0,flag);recompute(s,p);}}
